from datetime import datetime
from types import SimpleNamespace
import unittest
from unittest.mock import MagicMock, patch

import config
import database
import friends
import models
import ui_components


NOW = datetime(2026, 11, 15, 12)


class ProvenanceUITests(unittest.TestCase):
    """Exercise shared display and action boundaries with synthetic event values only."""

    def setUp(self):
        """Use inert native-widget doubles; no app, database file or network is started."""
        self.ui = MagicMock()
        self.ui.session_state = {}
        self.ui.button.return_value = False
        self.addCleanup(patch.stopall)
        patch.object(config, 'UNICLUBS_FEED_ENABLED', False).start()
        patch.object(ui_components, 'st', self.ui).start()
        self.event = models.UnisportCourse(
            event_id=42, series_id=6, title='Synthetic public course',
            location='', location_type='tba', direction_key='sports',
            bundle_key='sports_other', bundle_name='Other', start=datetime(2026, 11, 16, 7),
            end=datetime(2026, 11, 16, 8), status='unknown', provenance_kind='website',
            verification_url=config.UNISPORT_SCHEDULE_API_URL + '?example=synthetic',
            verified_at='2026-11-15 10:00:00', forecast_anchor_date='2026-11-06',
            evidence_weeks=3, source_url='', registration_url='')
        self.profile = SimpleNamespace(user_id=1)

    def test_dated_website_evidence_is_distinct_from_projection(self):
        """A website badge uses its saved check time, while projection shows its own evidence."""
        ui_components.render_event_provenance(self.event, detailed=True)
        self.ui.badge.assert_called_with('Website checked', color='blue')
        self.assertIn('15.11.2026 at 10:00', self.ui.caption.call_args.args[0])
        self.ui.link_button.assert_called_with('Verification source', self.event.verification_url)
        self.ui.reset_mock()
        self.event.provenance_kind = 'projected'
        ui_components.render_event_provenance(self.event, detailed=True)
        self.ui.badge.assert_called_with('Provisional', color='gray')
        caption = self.ui.caption.call_args.args[0]
        self.assertIn('3 of 4 observed weeks', caption)
        self.assertIn('2026-11-06', caption)
        self.ui.link_button.assert_not_called()

    def test_missing_provenance_never_looks_website_checked(self):
        """Legacy/demo rows receive no invented website badge or verification source."""
        self.event.provenance_kind = None
        ui_components.render_event_provenance(self.event, detailed=True)
        self.ui.badge.assert_not_called()
        self.ui.link_button.assert_not_called()
        self.assertIn('No website check', self.ui.caption.call_args.args[0])

    def test_official_calendar_link_selects_the_exact_local_date(self):
        """The normal public link opens the sport calendar rather than its raw JSON endpoint."""
        ui_components._public_links(self.event)
        self.ui.link_button.assert_called_once_with(
            'Official sport calendar', config.UNISPORT_PUBLIC_SCHEDULE_URL
            + '?language=de&selectedDate=2026-11-16')

    def test_unknown_event_confirmation_is_disabled_before_any_write(self):
        """An unknown event remains inspectable but cannot trigger a planning POST from the UI."""
        with patch.object(database, 'get_interaction', return_value=None), \
                patch.object(ui_components, '_interaction_action') as action, \
                patch.object(ui_components, '_public_links') as links:
            ui_components._dialog_actions('connection', self.profile, self.event, NOW)
        self.ui.button.assert_called_once_with(
            'Confirm', type='primary', disabled=True, key='ww_confirm_event')
        action.assert_not_called()
        links.assert_called_once_with(self.event)
        self.assertIn('Availability has not been verified', self.ui.caption.call_args.args[0])

    def test_unknown_availability_disables_invitation_send_and_accept(self):
        """Unknown status blocks both send controls and a previously stored pending invitation."""
        with patch.object(friends, 'get_friends_df') as choices:
            ui_components._invite_controls('connection', self.profile, self.event, NOW)
        choices.assert_not_called()
        self.ui.multiselect.assert_not_called()
        accept, decline = MagicMock(), MagicMock()
        accept.button.return_value = False
        decline.button.return_value = False
        self.ui.columns.return_value = [accept, decline]
        invitation = {'id': 6, 'event_id': 42, 'status': 'pending',
                      'start_time': '2026-11-16 07:00:00', 'event_status': 'unknown'}
        with patch.object(friends, 'respond_to_invitation') as response:
            ui_components.render_invitation_response('connection', invitation, NOW)
        accept.button.assert_called_once_with('Accept', disabled=True, key='ww_received_6_accept')
        response.assert_not_called()
        self.assertIn('Availability is unverified', self.ui.caption.call_args.args[0])

    def test_api_health_cache_is_scoped_to_the_active_catalogue(self):
        """A healthy API from another catalogue cannot share a positive cached health key."""
        with patch.object(ui_components, 'cached_connection', return_value='connection'), \
                patch.object(database, 'get_catalogue_id', return_value='reviewed-fixture',
                             create=True), \
                patch.object(ui_components, 'cached_api_available', return_value=False) as health:
            self.assertFalse(ui_components.api_available(NOW))
        health.assert_called_once_with('reviewed-fixture')

    def test_reviewed_sidebar_shows_evidence_totals_without_demo_labels(self):
        """Real catalogue counts stay separate from synthetic users and placeholder badges."""
        with patch.object(ui_components, 'cached_connection', return_value='connection'), \
                patch.object(ui_components, 'api_available', return_value=False), \
                patch.object(database, 'get_current_user_id', return_value=None), \
                patch.object(database, 'is_reviewed_catalogue', return_value=True, create=True), \
                patch.object(database, 'get_provenance_counts',
                             return_value={'website': 2, 'projected': 1, 'unspecified': 0},
                             create=True), \
                patch.object(database, 'get_demo_counts',
                             return_value={'placeholder_series': 0, 'synthetic_users': 0}):
            ui_components.render_sidebar_status()
        self.ui.badge.assert_called_once_with('Reviewed sport catalogue', color='blue')
        captions = [call.args[0] for call in self.ui.caption.call_args_list]
        self.assertIn('2 website checked · 1 provisional dates.', captions)


if __name__ == '__main__':
    unittest.main()
